    20	const RawBody = Schema.Struct({
    21	  token: Schema.optional(Schema.String),
    22	  editKey: Schema.optional(Schema.String),
    23	  edit_key: Schema.optional(Schema.String),
    24	  editKeyHash: Schema.optional(Schema.String),
    25	  edit_key_hash: Schema.optional(Schema.String),
    26	  questionVersionId: Schema.optional(Schema.String),
    27	  value: Schema.optional(Schema.NullOr(Schema.Int)),
    28	  comment: Schema.optional(Schema.NullOr(Schema.String)),
    29	  answers: Schema.optional(Schema.Array(RawAnswer)),
    30	});
    31	type RawBody = typeof RawBody.Type;
    32	
    33	const decodeBody = Schema.decodeUnknownOption(RawBody);
    34	
    35	const parseBody = (req: HttpServerRequest): Effect.Effect<RawBody> =>
    36	  Effect.gen(function* () {
    37	    const text = yield* req.text.pipe(Effect.orDie);
    38	    if (!text || text.trim().length === 0) return {};
    39	    try {
    40	      const parsed = JSON.parse(text);
    41	      return Option.getOrElse(decodeBody(parsed), (): RawBody => ({}));
    42	    } catch {
    43	      return {};
    44	    }
    45	  });
    46	
    47	const extractAnswers = (body: RawBody): ReadonlyArray<SubmissionAnswer> => {
    48	  if (body.answers !== undefined && body.answers.length > 0) {
    49	    return body.answers.map((item) => ({
    50	      questionVersionId: QuestionVersionId.make(item.questionVersionId),
    51	      value: item.value ?? null,
    52	      comment: item.comment ?? null,
    53	    }));
    54	  }
    55	  if (body.questionVersionId !== undefined && body.questionVersionId.length > 0) {
    56	    return [
    57	      {
    58	        questionVersionId: QuestionVersionId.make(body.questionVersionId),
    59	        value: body.value ?? null,
    60	        comment: body.comment ?? null,
    61	      },
    62	    ];
    63	  }
    64	  return [];
    65	};
