    73	  "Submission",
    74	  Effect.gen(function* () {
    75	    const stack = yield* Stack;
    76	    const hostname = hostnameFor(stack.stage, "submit");
    77	    return {
    78	      main: import.meta.url,
    79	      observability: {
    80	        enabled: false,
    81	        logs: { enabled: false, invocationLogs: false, persist: false },
    82	        traces: { enabled: false, persist: false },
    83	      },
    84	      logpush: false,
    85	      tailConsumers: [],
