    87	      ...(hostname === undefined ? {} : { domain: hostname }),
    88	    };
    89	  }),
    90	  Effect.gen(function* () {
    91	    const organizations = yield* Organization;
    92	    const database = yield* Cloudflare.D1.QueryDatabase(yield* Database);
