   119	        const tokenFromHeader = request.headers["x-invitation-token"];
   120	        const editKeyFromHeader = request.headers["x-edit-key"];
   121	
   122	        const token = body.token ?? tokenFromQuery ?? tokenFromHeader;
   123	        const editKey = body.editKey ?? body.edit_key ?? editKeyFromQuery ?? editKeyFromHeader;
