   139	            .prepare("SELECT organization_id, round_id, person_id FROM invitation_index WHERE token_hash = ?")
   140	            .bind(tokenHash)
   141	            .first<{ organization_id: string; round_id: string; person_id: string }>()
   142	            .pipe(Effect.orDie);
   143	          if (row === null) {
   144	            return yield* HttpServerResponse.json({ error: "Invitation not found" }, { status: 404 });
   145	          }
   146	          const context = yield* organizations
   147	            .getByName(row.organization_id)
   148	            .getSubmissionRoundContext(row.round_id, row.person_id)
   149	            .pipe(Effect.orDie);
   150	          if (context === null) {
   151	            return yield* HttpServerResponse.json({ error: "Round not found" }, { status: 404 });
   152	          }
   153	          return yield* HttpServerResponse.json(context);
   154	        }
   155	
   156	        if (
   157	          (path === "/first-answer" || (path === "/answer" && token !== undefined)) &&
   158	          request.method === "POST"
   159	        ) {
   160	          if (token === undefined) {
   161	            return yield* HttpServerResponse.json({ error: "Missing invitation token" }, { status: 400 });
   162	          }
   163	          const rawEditKeyHash =
   164	            body.editKeyHash ??
   165	            body.edit_key_hash ??
   166	            url.searchParams.get("editKeyHash") ??
   167	            url.searchParams.get("edit_key_hash") ??
   168	            undefined;
   169	
   170	          if (rawEditKeyHash === undefined) {
   171	            return yield* HttpServerResponse.json({ error: "Missing edit key hash" }, { status: 400 });
   172	          }
   173	
   174	          const tokenHash = yield* Effect.promise(() => hashToken(token));
   175	          const row = yield* database
   176	            .prepare("SELECT organization_id, round_id, person_id FROM invitation_index WHERE token_hash = ?")
   177	            .bind(tokenHash)
   178	            .first<{ organization_id: string; round_id: string; person_id: string }>()
   179	            .pipe(Effect.orDie);
   180	          if (row === null) {
   181	            return yield* HttpServerResponse.json({ error: "Invitation not found" }, { status: 404 });
   182	          }
   183	
   184	          const answers = extractAnswers(body);
   185	          const result = yield* organizations
   186	            .getByName(row.organization_id)
   187	            .recordFirstAnswer(row.round_id, row.person_id, rawEditKeyHash, answers)
   188	            .pipe(Effect.orDie);
   189	
   190	          if (result._tag === "AlreadyAnswered") {
   191	            return yield* HttpServerResponse.json({ error: "already answered" }, { status: 409 });
   192	          }
   193	          if (result._tag === "RoundNotOpen") {
   194	            return yield* HttpServerResponse.json({ error: "round not open" }, { status: 400 });
   195	          }
   196	
   197	          yield* database
   198	            .prepare(
   199	              "INSERT INTO submission_index (edit_key_hash, organization_id, round_id) VALUES (?, ?, ?) ON CONFLICT (edit_key_hash) DO NOTHING",
   200	            )
   201	            .bind(rawEditKeyHash, row.organization_id, row.round_id)
   202	            .run()
   203	            .pipe(Effect.orDie);
   204	
   205	          return yield* HttpServerResponse.json({ saved: true, shownToLead: result.shownToLead });
   206	        }
   207	
   208	        if (path === "/answer" && request.method === "POST") {
   209	          const rawEditKeyHash =
   210	            editKey !== undefined
   211	              ? yield* Effect.promise(() => hashToken(editKey))
   212	              : (body.editKeyHash ??
   213	                body.edit_key_hash ??
   214	                url.searchParams.get("editKeyHash") ??
   215	                url.searchParams.get("edit_key_hash") ??
   216	                undefined);
   217	
   218	          if (rawEditKeyHash === undefined) {
   219	            return yield* HttpServerResponse.json({ error: "Missing edit key" }, { status: 400 });
   220	          }
   221	
   222	          const row = yield* database
   223	            .prepare("SELECT organization_id, round_id FROM submission_index WHERE edit_key_hash = ?")
   224	            .bind(rawEditKeyHash)
   225	            .first<{ organization_id: string; round_id: string }>()
   226	            .pipe(Effect.orDie);
   227	          if (row === null) {
   228	            return yield* HttpServerResponse.json({ error: "Submission not found" }, { status: 404 });
   229	          }
