   232	          const result = yield* organizations
   233	            .getByName(row.organization_id)
   234	            .saveAnswer(rawEditKeyHash, answers)
   235	            .pipe(Effect.orDie);
   236	
   237	          if (result._tag === "SubmissionNotFound") {
   238	            return yield* HttpServerResponse.json({ error: "Submission not found" }, { status: 404 });
   239	          }
   240	          if (result._tag === "RoundNotOpen") {
   241	            return yield* HttpServerResponse.json({ error: "round not open" }, { status: 400 });
   242	          }
   243	
   244	          return yield* HttpServerResponse.json({ saved: true, shownToLead: result.shownToLead });
   245	        }
   246	
   247	        if (path === "/my-answers" && request.method === "POST") {
   248	          const rawEditKeyHash =
   249	            editKey !== undefined
   250	              ? yield* Effect.promise(() => hashToken(editKey))
   251	              : (body.editKeyHash ??
   252	                body.edit_key_hash ??
   253	                url.searchParams.get("editKeyHash") ??
   254	                url.searchParams.get("edit_key_hash") ??
   255	                undefined);
   256	
   257	          if (rawEditKeyHash === undefined) {
   258	            return yield* HttpServerResponse.json({ error: "Missing edit key" }, { status: 400 });
   259	          }
   260	
   261	          const row = yield* database
   262	            .prepare("SELECT organization_id, round_id FROM submission_index WHERE edit_key_hash = ?")
   263	            .bind(rawEditKeyHash)
   264	            .first<{ organization_id: string; round_id: string }>()
   265	            .pipe(Effect.orDie);
   266	          if (row === null) {
   267	            return yield* HttpServerResponse.json({ error: "Submission not found" }, { status: 404 });
   268	          }
   269	
   270	          const result = yield* organizations
   271	            .getByName(row.organization_id)
   272	            .getMyAnswers(rawEditKeyHash)
   273	            .pipe(Effect.orDie);
   274	
   275	          if (result._tag === "SubmissionNotFound") {
   276	            return yield* HttpServerResponse.json({ error: "Submission not found" }, { status: 404 });
   277	          }
   278	
   279	          return yield* HttpServerResponse.json({ answers: result.answers });
   280	        }
   281	
   282	        return yield* HttpServerResponse.json({ error: "not found" }, { status: 404 });
