    const q1text = document.getElementById("q1text");
    if (q1text instanceof HTMLElement) {
      q1text.textContent = q1.text;
    }
  }

  if (saveBtn instanceof HTMLButtonElement) {
    saveBtn.disabled = false;
  }

  mark("meaningful");

  let firstSaved = context.hasAnswered;

  const doFirstSave = async (ratingVal: number): Promise<void> => {
    if (firstSaved) return;
    if (saveBtn instanceof HTMLButtonElement) {
      saveBtn.disabled = true;
    }
    mark("first-save-start");
    try {
      editKey = generateEditKey();
      const editKeyHash = await sha256Hex(editKey);
      window.localStorage.setItem(roundStorageKey, editKey);

      await postJson(`${submitOrigin}/first-answer`, {
        token,
        editKeyHash,
        questionVersionId: q1 ? q1.id : "",
        value: ratingVal,
      });

      if (q1) {
        keepAnswer(() => window.localStorage, context.roundId, q1.id, { value: ratingVal }, Date.now());
      }
      firstSaved = true;
      // Invariant: after the first save, no request carries the token (ADR 0005)
      window.sessionStorage.removeItem("sb_token");
      window.__sb_token = undefined;

      mark("first-save-end");
      mark("screen2");
      goToRemainingScreens();
    } catch (err: unknown) {
      if (typeof err === "object" && err !== null && "status" in err && err.status === 409) {
        showStateMessage(message("answer.state.alreadyAnswered"));
        return;
      }
      showError(message("answer.error"));
      if (saveBtn instanceof HTMLButtonElement) {
        saveBtn.disabled = false;
        }),
      )
      .pipe(
        Effect.catch((err: unknown) => {
          if (err instanceof SubmissionNotFound || err instanceof RoundNotOpen) {
            return Effect.fail(err);
          }
          return Effect.die(err);
        }),
      );

  const getMyAnswers = (
    editKeyHash: string,
  ): Effect.Effect<ReadonlyArray<SubmissionAnswer>, SubmissionNotFound> =>
    sql
      .withTransaction(
        Effect.gen(function* () {
          const sub = yield* getSubmissionByEditKeyHash(editKeyHash);
          if (sub === null) {
            return yield* new SubmissionNotFound();
          }
          const rows = yield* sql<{
            question_version_id: string;
            value: number | null;
            comment: string | null;
          }>`SELECT question_version_id, value, comment FROM answer WHERE submission_id = ${sub.id} ORDER BY question_version_id ASC`;

          return rows.map((r) => ({
            questionVersionId: QuestionVersionId.make(r.question_version_id),
            value: r.value,
            comment: r.comment,
          }));
        }),
      )
      .pipe(
        Effect.catch((err: unknown) => {
          if (err instanceof SubmissionNotFound) {
            return Effect.fail(err);
          }
          return Effect.die(err);
        }),
      );

  const getSubmissionRoundContext = (
    roundId: RoundId,
    personId: PersonId | null,
            return yield* rounds.getSubmissionRoundContext(
              RoundId.make(roundId),
              personId === null ? null : PersonId.make(personId),
              dirState.minimumGroupSize,
            );
          }),
        recordFirstAnswer: (
          roundId: string,
          personId: string,
          editKeyHash: string,
          answers: ReadonlyArray<SubmissionAnswer>,
        ) =>
          Effect.gen(function* () {
            const dirState = yield* directory.load;
            return yield* rounds
              .recordFirstAnswer(
                RoundId.make(roundId),
                PersonId.make(personId),
                editKeyHash,
                answers,
                dirState.people,
              )
              .pipe(
                Effect.map((res) => ({ _tag: "Success" as const, ...res })),
                Effect.catchTag("AlreadyAnswered", () =>
                  Effect.succeed({ _tag: "AlreadyAnswered" as const }),
                ),
                Effect.catchTag("RoundNotOpen", () => Effect.succeed({ _tag: "RoundNotOpen" as const })),
              );
          }),
        saveAnswer: (editKeyHash: string, answers: ReadonlyArray<SubmissionAnswer>) =>
          Effect.gen(function* () {
            const dirState = yield* directory.load;
            return yield* rounds.saveAnswer(editKeyHash, answers, dirState.people).pipe(
              Effect.map((res) => ({ _tag: "Success" as const, ...res })),
              Effect.catchTag("SubmissionNotFound", () =>
                Effect.succeed({ _tag: "SubmissionNotFound" as const }),
              ),
              Effect.catchTag("RoundNotOpen", () => Effect.succeed({ _tag: "RoundNotOpen" as const })),
            );
          }),
        getMyAnswers: (editKeyHash: string) =>
          rounds.getMyAnswers(editKeyHash).pipe(
            Effect.map((answers) => ({ _tag: "Success" as const, answers })),
            Effect.catchTag("SubmissionNotFound", () =>
              Effect.succeed({ _tag: "SubmissionNotFound" as const }),
            ),
          ),
        deleteParticipationForPerson: (personId: string) =>
          rounds.deleteParticipationForPerson(PersonId.make(personId)),

        get: (id: string) =>
          sql<{ id: string; name: string }>`SELECT id, name FROM organization WHERE id = ${id}`.pipe(
            Effect.map((rows) => rows[0] ?? null),
            Effect.orDie,
          ),
